             ExpiresAt = DateTime.UtcNow.AddDays(30)
         };

         var receipt = $"Order {order.Id} created at {DateTime.Now}";
         File.WriteAllText(Path.Combine(Path.GetTempPath(), $"{order.Id}.txt"), receipt);

